{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Under the replacement text for Tennessee Code Annotated, Section 49-6-1021(b)(1), physical activity may include walking, jumping rope, playing volleyball, or other forms of physical activity that promote fitness and well-being.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(A) Walking, jumping rope, playing volleyball, or other forms of physical\n\n activity that promote fitness and well-being;"
    },
    {
      "id": "P2",
      "proposition": "Physical activity may include structured movement breaks.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(B) Structured movement breaks; and"
    },
    {
      "id": "P3",
      "proposition": "Physical activity may include time a student spends in a physical education class if the students are physically active during that time.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(C) Time spent by a student in a physical education class if during such\n\n time the students are physically active."
    },
    {
      "id": "P4",
      "proposition": "Walking to and from class does not count as physical activity for purposes of Section 49-6-1021.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(2) Walking to and from class is not physical activity for purposes of this section."
    },
    {
      "id": "P5",
      "proposition": "Replaces Tennessee Code Annotated, Section 49-6-1021(b)(2)(A)(ii), with text excluding time during which a student is permitted to use an electronic device.",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "(ii) Does not include time during which a student is permitted to use an electronic\n\n device; and"
    },
    {
      "id": "P6",
      "proposition": "A teacher may prevent a student from participating in physical activity to improve the student's behavior.",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "(B) A teacher may prevent a student from participating in physcial activity to\n\n improve the student's behavior."
    },
    {
      "id": "P7",
      "proposition": "The act takes effect July 1, 2026, and applies to the 2026-2027 school year and each school year thereafter.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "This act takes effect July 1, 2026, the public welfare requiring it, and\n\napplies to the 2026-2027 school year and each school year thereafter."
    }
  ]
}
